package com.devmanchego.javaguard.compile;

import com.devmanchego.javaguard.model.Finding;
import com.devmanchego.javaguard.model.Severity;

import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * The confidence guard (specification &sect;8.2 step 6): if in-process
 * compilation reports an error in a file that the project's own last
 * successful full build compiled unchanged, in-process compilation for that
 * module is untrustworthy for the rest of the session (an exotic annotation
 * processor, a resource generated by another build step, ...), and further
 * in-process errors for it are downgraded to INFO with a note rather than
 * blocking the agent on a false alarm.
 *
 * <p>This class only tracks the per-session unreliable-module set and
 * applies the downgrade; deciding <em>when</em> to call
 * {@link #recordDiscrepancy(String)} - comparing an in-process result
 * against the project's last successful full build - is the gate's job
 * (Phase 7+), since only the gate has both results to compare. One instance
 * is scoped to one session; a fresh session starts with nothing marked
 * unreliable.
 */
public final class InProcessConfidenceGuard {

    private final Set<String> unreliableModules = ConcurrentHashMap.newKeySet();

    /** Marks {@code moduleKey} unreliable for the rest of this session. */
    public void recordDiscrepancy(String moduleKey) {
        unreliableModules.add(moduleKey);
    }

    public boolean isUnreliable(String moduleKey) {
        return unreliableModules.contains(moduleKey);
    }

    /**
     * {@code finding} unchanged if {@code moduleKey} is not marked
     * unreliable; otherwise a copy downgraded to {@link Severity#INFO} with a
     * note appended to the remediation explaining why.
     */
    public Finding apply(String moduleKey, Finding finding) {
        if (!isUnreliable(moduleKey) || finding.severity() == Severity.INFO) {
            return finding;
        }
        String note = " (downgraded: in-process compilation disagreed with the last successful full build for this "
                + "module earlier this session, so its errors are no longer trusted).";
        return new Finding(finding.ruleId(), finding.title(), finding.category(), Severity.INFO, finding.engine(),
                finding.file(), finding.line(), finding.column(), finding.endLine(), finding.message(),
                finding.remediation() + note, finding.snippet(), copy(finding.detail()), finding.fingerprint());
    }

    private static Map<String, String> copy(Map<String, String> detail) {
        return Map.copyOf(detail);
    }
}
